From 2eb309a74ab1121a54af5ed9b08b1224892a9313 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 19:37:04 +0100
Subject: [PATCH] containments/folder: add Sticky Note to the desktop's Create
 New menu

Creating a sticky note required knowing that it is a widget and adding
it from the widget explorer or dragging text onto the desktop. The new
Sticky Note entry in Create New adds one where the menu was opened.

BUG: 523422
---
 .../desktop/plugins/folder/foldermodel.cpp    | 20 +++++++++++++++++++
 1 file changed, 20 insertions(+)

diff --git a/containments/desktop/plugins/folder/foldermodel.cpp b/containments/desktop/plugins/folder/foldermodel.cpp
index 678bae687c..914ac0c533 100644
--- a/containments/desktop/plugins/folder/foldermodel.cpp
+++ b/containments/desktop/plugins/folder/foldermodel.cpp
@@ -73,6 +73,7 @@
 #include <KLocalizedString>
 #include <KNotification>
 #include <KNotificationJobUiDelegate>
+#include <KPluginMetaData>
 #include <KPropertiesDialog>
 #include <KProtocolInfo>
 #include <KSharedConfig>
@@ -1898,6 +1899,14 @@ void FolderModel::createActions()

     m_actionCollection.addAction(QStringLiteral("newMenu"), m_newMenu);

+    QAction *newStickyNote = new QAction(QIcon::fromTheme(QStringLiteral("knotes")), i18nc("@item:inmenu Create New", "Sticky Note"), this);
+    connect(newStickyNote, &QAction::triggered, this, [this] {
+        if (Plasma::Containment *containment = m_applet ? m_applet->containment() : nullptr) {
+            containment->createApplet(QStringLiteral("org.kde.plasma.notes"), QVariantList(), QRectF(localMenuPosition(), QSizeF(-1, -1)));
+        }
+    });
+    m_actionCollection.addAction(QStringLiteral("newStickyNote"), newStickyNote);
+
     m_copyToMenu = new KFileCopyToMenu(nullptr);
 }

@@ -1952,6 +1961,17 @@ void FolderModel::updateActions()
     if (m_newMenu) {
         m_newMenu->checkUpToDate();
         m_newMenu->setWorkingDirectory(m_dirModel->dirLister()->url());
+
+        if (QAction *newStickyNote = m_actionCollection.action(QStringLiteral("newStickyNote"))) {
+            const Plasma::Containment *containment = m_applet ? m_applet->containment() : nullptr;
+            newStickyNote->setVisible(m_usedByContainment && containment && containment->immutability() == Plasma::Types::Mutable
+                                      && KPluginMetaData::findPluginById(QStringLiteral("plasma/applets"), QStringLiteral("org.kde.plasma.notes")).isValid());
+            // KNewFileMenu clears and refills its menu when the templates change
+            if (!m_newMenu->menu()->actions().contains(newStickyNote)) {
+                m_newMenu->menu()->addSeparator();
+                m_newMenu->menu()->addAction(newStickyNote);
+            }
+        }
         // we need to set here as well, when the menu is shown via AppletInterface::eventFilter
         m_menuPosition = QCursor::pos();

